INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 13, 'w13-skeleton', 0, 'lab', 'Минимальный документ', 'Напишите с нуля каркас страницы: доктайп, элемент html с языком ru, в голове — кодировка utf-8, вьюпорт (width=device-width) и заголовок страницы «Кофейня», в теле — заголовок первого уровня.', '', 'Порядок: <!doctype html>, затем html lang="ru" с двумя детьми head и body. В head — meta charset, meta name="viewport" content="width=device-width, initial-scale=1" и title.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 13, 'w13-head', 1, 'lab', 'Голова страницы', 'Дополните голову документа: у страницы должно быть название «Рецепты», кодировка utf-8, вьюпорт с width=device-width, подключённые стили style.css и скрипт app.js с отложенной загрузкой.', '', 'Таблицы стилей подключает link с rel="stylesheet" и href. У скрипта нужен атрибут defer, а не async.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 13, 'w13-headings', 2, 'lab', 'Заголовки без пропусков', 'В странице перепутаны уровни заголовков: после h1 сразу идёт h3. Исправьте их: разделы «Сорта» и «Заварка» — заголовки второго уровня, а «Арабика» и «Робуста» — третьего. Заголовков четвёртого уровня быть не должно.', '', 'Уровень выбирают по месту в структуре: h1 — название, h2 — разделы, h3 — части разделов. Пропускать уровни нельзя.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 13, 'w13-nav', 3, 'lab', 'Навигация списком ссылок', 'Сделайте меню сайта: элемент nav, внутри него маркированный список из трёх пунктов со ссылками «Главная», «Меню» и «Контакты». У каждой ссылки должен быть адрес href.', '', 'Меню — это список ссылок: nav > ul > li > a. Каждый пункт li содержит одну ссылку.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 13, 'w13-layout', 4, 'lab', 'Шапка, главное, подвал', 'Страница собрана из абзацев. Разметьте её смысловыми контейнерами: название сайта — в header, основной текст — в main, строка с правами — в footer. Контейнеры идут по порядку и по одному, прямо в body.', '', 'Нужны элементы header, main и footer; main на странице один. Текст сохраните, меняйте только обёртки.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 13, 'w13-article', 5, 'lab', 'Статья с датой', 'Разметьте запись блога. Заголовок страницы «Блог» — h1. Сама запись — элемент article: внутри заголовок второго уровня, дата в элементе time с атрибутом datetime и абзац текста.', '', 'time пишут так: <time datetime="2026-05-06">6 мая 2026</time>. Заголовок записи — h2, потому что h1 уже занят названием блога.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 13, 'w13-link', 6, 'lab', 'Внешняя ссылка', 'Ссылка ведёт на чужой сайт. Сделайте так, чтобы она открывалась в новой вкладке безопасно: добавьте target и rel с обоими значениями защиты. Текст и адрес оставьте.', '', 'target="_blank" открывает новую вкладку, а rel="noopener noreferrer" не даёт открытой странице управлять вашей.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 13, 'w13-anchor', 7, 'lab', 'Якорная ссылка', 'Сделайте ссылку «К ценам» якорем: она должна вести на заголовок «Цены» на этой же странице. Для этого заголовку нужен идентификатор prices, а ссылке — адрес из решётки и этого идентификатора.', '', 'Идентификатор задают атрибутом id, а ссылка на него начинается с решётки: href="#prices".', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 13, 'w13-dl', 8, 'lab', 'Список определений', 'Термины записаны абзацами. Превратите их в список определений: элемент dl, каждый термин — в dt, пояснение — в dd. Абзацев остаться не должно.', '', 'Структура пары: <dt>термин</dt><dd>пояснение</dd>, все пары лежат внутри одного dl.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 13, 'w13-quote', 9, 'lab', 'Цитата с источником', 'Оформите фразу как цитату: длинную — элементом blockquote с атрибутом cite, в котором лежит адрес источника (начинается с https). Абзац-обёртка не нужен.', '', 'blockquote — цитата отдельным блоком, адрес первоисточника записывают в cite: <blockquote cite="https://…">.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 13, 'w13-code', 10, 'lab', 'Код в pre и code', 'Короткий листинг набран абзацем с переносами через br. Оформите его правильно: многострочный код — в pre, а внутри pre — элемент code. Элементов br быть не должно.', '', 'Пробелы и переносы строк внутри pre сохраняются, поэтому br не нужен. Структура: <pre><code>…</code></pre>.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 13, 'w13-soup', 11, 'lab', 'Из див-супа в семантику', 'Страница целиком собрана из div с классами. Перепишите её: header с названием и навигацией (nav со списком ссылок), main с заголовком h1 и абзацем, footer. Дивов с классами не должно остаться.', '', 'div.top → header, div.menu → nav со списком ul, div.content → main, div.title → h1, div.text → p, div.bottom → footer. Пункты меню — li со ссылкой.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 13, 'w13-figure', 12, 'lab', 'Картинка с подписью', 'Оформите иллюстрацию: элемент figure, внутри него картинка img с коротким описанием в alt и подпись в figcaption. Путь к файлу сохраните.', '', 'Структура: <figure><img src="…" alt="описание"><figcaption>подпись</figcaption></figure>. Описание в alt не должно быть пустым.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 13, 'w13-inline', 13, 'lab', 'Мелкие смысловые элементы', 'В абзаце есть сокращение, дата и важная мысль. Разметьте их: HTML — элементом abbr с расшифровкой в title, дату — элементом time с datetime="2026-05-06", слова «очень важно» — элементом strong, слово «разметки» — элементом mark.', '', 'abbr получает расшифровку в title, time — машинную дату в datetime, strong — важное, mark — выделенное для поиска. Текст абзаца менять не нужно.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 13, 'w13-legacy', 14, 'lab', 'Без устаревших тегов', 'Фрагмент написан по правилам девяностых: центрирование и цвет — через center и font. Перепишите его: заголовок «Распродажа» — h1, текст — абзац p. Тегов center и font, а также атрибутов style, color и align быть не должно.', '', 'Оформление — задача стилей, а не разметки. В разметке остаётся смысл: заголовок и абзац.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 13, 'w13-parse', 15, 'lab', 'Документ без ошибок разбора', 'Браузер молча чинит разметку, но ошибки остаются: незакрытый заголовок, перепутанный порядок закрытия тегов, лишний закрывающий тег. Исправьте документ так, чтобы разбор прошёл без замечаний. Заголовок «Покупки» и два пункта списка сохраните.', '', 'Каждый открытый тег закрывается, причём в обратном порядке: <b><i>…</i></b>. Лишний закрывающий тег просто удалите.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 13, 'w13-a11y', 16, 'lab', 'Доступная страница', 'Страница подписки недоступна для скринридера. Исправьте: добавьте язык документа, заголовок первого уровня вместо div «Подписка на рассылку», описание для логотипа в alt, подпись label для поля почты и оберните содержимое в main.', '', 'Поле связывают с подписью через for и id: <label for="email">…</label><input id="email">. Логотипу нужен непустой alt.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 13, 'w13-sections', 17, 'lab', 'Статья, разделы и врезка', 'Соберите страницу статьи: h1 с названием, в main — элемент article с двумя разделами section (у каждого заголовок h2 и абзац), а рядом с ним врезка aside с абзацем.', '', 'Структура: main > article > section × 2 (каждая с h2 и p), а aside — побочное содержимое с абзацем внутри.', '{}');
